globalThis.EluceniaToolLocales={"id":"nafld-fibrosis-score","clinicalApproval":"not-performed","professionalLanguageApproval":"not-performed","locales":{"pt-BR":{"tool":{"id":"nafld-fibrosis-score","title":"NAFLD Fibrosis Score (NFS)","summary":"Fibrose avançada na esteatose hepática","lead":"Escore não invasivo desenvolvido para a doença hepática gordurosa não alcoólica (hoje MASLD) que separa pacientes com baixa e alta probabilidade de fibrose avançada (F3–F4).","fields":[["idade","Idade","num",{"min":18,"max":100,"unit":"anos","ph":"50"}],["imc","IMC","num",{"min":12,"max":80,"step":0.1,"unit":"kg/m²","ph":"30"}],["dm","Glicemia de jejum alterada ou diabetes","radio",{"opts":{"0":"Não","1":"Sim"}}],["ast","AST (TGO)","num",{"min":1,"max":5000,"unit":"U/L","ph":"40"}],["alt","ALT (TGP)","num",{"min":1,"max":5000,"unit":"U/L","ph":"50"}],["plq","Plaquetas","num",{"min":5,"max":1500,"unit":"× 10³/mm³","ph":"200"}],["alb","Albumina","num",{"min":1,"max":6,"step":0.1,"unit":"g/dL","ph":"4,0"}]],"formula":"<p>NFS = −1,675 + 0,037 × idade + 0,094 × IMC + 1,13 × (glicemia alterada/diabetes: 1) + 0,99 × AST/ALT − 0,013 × plaquetas (10⁹/L) − 0,66 × albumina (g/dL).</p>","sources":[["Angulo P et al. The NAFLD fibrosis score: a noninvasive system that identifies liver fibrosis in patients with NAFLD. Hepatology, 2007.","https://doi.org/10.1002/hep.21496"],["McPherson S et al. Age as a confounding factor for the accurate non-invasive diagnosis of advanced NAFLD fibrosis. Am J Gastroenterol, 2017.","https://doi.org/10.1038/ajg.2016.453"],["Rinella ME et al. AASLD Practice Guidance on the clinical assessment and management of nonalcoholic fatty liver disease. Hepatology, 2023.","https://doi.org/10.1097/HEP.0000000000000323"]],"methodVersion":"NFS de Angulo et al. (2007), seis variáveis; fórmula e cortes originais conferidos na Tabela 1 de McPherson et al. (2017). Esta implementação usa o corte inferior 0,12 para idade ≥65 anos; o corte superior continua 0,676.","implementationVersion":"nafld-fibrosis-score@native-2026-10-05+325fbd4c60c4","limits":"O modelo original foi derivado de NAFLD confirmada por biópsia, não de toda população hoje denominada MASLD. McPherson (2017) avaliou serviços especializados europeus, excluiu outras hepatopatias e consumo excessivo de álcool e encontrou desempenho fraco em pessoas ≤35 anos. A Figura 4 e sua legenda divergem nas fronteiras de 35 e 65 anos; essas idades exatas não receberam adjudicação clínica aqui. O limiar inferior de 0,12 para idade ≥65 é a política declarada desta implementação. Plaquetas ×10³/mm³ equivalem numericamente a ×10⁹/L; albumina deve estar em g/dL. O escore é exibido com três casas decimais; a classificação usa os limites estritos sem arredondar o escore. Valores intermediários são inconclusivos; o NFS isolado não confirma F3–F4. Revisão clínica e de idiomas por profissionais independentes não realizada.","limitsLocale":"pt-BR","resultLabels":{"NAFLD Fibrosis Score (NFS)":"NAFLD Fibrosis Score (NFS)"},"resultUnits":{},"resultValues":{},"resultNarratives":[]},"shared":{"select":"Selecione","yes":"Sim","no":"Não","optional":"opcional","numeric":"Valor numérico","range":"intervalo","calculate":"Calcular","calculating":"Calculando…","clear":"Limpar","heading":"Calcular com transparência","intro":"Confira população, unidades e versão. O resultado apresenta a fórmula ou classificação, sem decisão terapêutica automática.","restricted":"Ficha disponível para consulta","restrictedNote":"Cálculo suspenso nesta edição. O inventário, a pendência e as fontes permanecem públicos.","resultNote":"Resultado da fórmula ou classificação. Interpretação, conduta e aplicabilidade dependem da avaliação profissional e da fonte selecionada.","invalid":"Não foi possível calcular com esses valores. Confira as condições de uso.","unavailable":"O serviço de cálculo está indisponível. Tente novamente.","connection":"Não foi possível consultar o serviço de cálculo. Verifique a conexão e tente novamente.","check":"Confira os valores informados.","fleischner":"Antes de calcular: referência para nódulos pulmonares incidentais. As recomendações não se aplicam a pessoas com menos de 35 anos, rastreamento de câncer de pulmão, imunossupressão ou câncer primário conhecido.","incompleteAssessment":"Sem avaliação completa, não é possível calcular a pontuação total."},"ui":{"brand":"ELUCENIA · código de integração","clinical":"Revisão clínica independente não realizada.","conditions":"condições, fontes e permissões","record":"Ficha e referências","code":"Código JavaScript","cases":"Casos de referência","language":"Idioma","formula":"Fórmula documentada","edition":"Edição do método","limits":"Limites e população","references":"Referências"}},"en":{"tool":{"id":"nafld-fibrosis-score","title":"NAFLD Fibrosis Score (NFS)","titleLocale":"en","summary":"Advanced fibrosis in hepatic steatosis","lead":"A noninvasive score developed for nonalcoholic fatty liver disease (now MASLD), separating low and high probability of advanced fibrosis (F3–F4).","fields":[["idade","Age","num",{"min":18,"max":100,"unit":"years","ph":"50","unitLocale":"en","displayLocale":"en"}],["imc","BMI","num",{"min":12,"max":80,"step":0.1,"unit":"kg/m²","ph":"30","unitLocale":"en","displayLocale":"en"}],["dm","Impaired fasting glucose or diabetes","radio",{"opts":{"0":"No","1":"Yes"},"unitLocale":"en","displayLocale":"en","optionLocales":{"0":"en","1":"en"}}],["ast","Aspartate aminotransferase (AST)","num",{"min":1,"max":5000,"unit":"U/L","ph":"40","unitLocale":"en","displayLocale":"en"}],["alt","Alanine aminotransferase (ALT)","num",{"min":1,"max":5000,"unit":"U/L","ph":"50","unitLocale":"en","displayLocale":"en"}],["plq","Platelets","num",{"min":5,"max":1500,"unit":"× 10³/mm³","ph":"200","unitLocale":"en","displayLocale":"en"}],["alb","Albumin","num",{"min":1,"max":6,"step":0.1,"unit":"g/dL","ph":"4.0","unitLocale":"en","displayLocale":"en"}]],"formula":"<p>NFS = −1.675 + 0.037 × age + 0.094 × BMI + 1.13 × (impaired glycemia/diabetes: 1) + 0.99 × AST/ALT − 0.013 × platelets (10⁹/L) − 0.66 × albumin (g/dL).</p>","sources":[["Angulo P et al. The NAFLD fibrosis score: a noninvasive system that identifies liver fibrosis in patients with NAFLD. Hepatology, 2007.","https://doi.org/10.1002/hep.21496"],["McPherson S et al. Age as a confounding factor for the accurate non-invasive diagnosis of advanced NAFLD fibrosis. Am J Gastroenterol, 2017.","https://doi.org/10.1038/ajg.2016.453"],["Rinella ME et al. AASLD Practice Guidance on the clinical assessment and management of nonalcoholic fatty liver disease. Hepatology, 2023.","https://doi.org/10.1097/HEP.0000000000000323"]],"methodVersion":"NFS by Angulo et al. (2007), six variables; the original formula and cutoffs were checked in Table 1 of McPherson et al. (2017). This implementation uses the lower cutoff of 0.12 at age ≥65 years; the upper cutoff remains 0.676.","methodVersionLocale":"en","implementationVersion":"nafld-fibrosis-score@native-2026-10-05+325fbd4c60c4","limits":"The original model was derived from biopsy-confirmed NAFLD, not from every population now termed MASLD. McPherson (2017) assessed European specialist clinics, excluded other liver diseases and excessive alcohol consumption, and found poor performance in people aged ≤35 years. Figure 4 and its caption differ at the age boundaries of 35 and 65; these exact ages have not been clinically adjudicated here. The lower cutoff of 0.12 at age ≥65 is the declared policy of this implementation. Platelets in ×10³/mm³ are numerically equivalent to ×10⁹/L; albumin must be in g/dL. The score is displayed to three decimal places; classification uses strict cutoffs without rounding the score. Intermediate values are inconclusive; NFS alone does not confirm F3–F4. Independent professional clinical and language review has not been performed.","limitsLocale":"en","resultLabels":{"NAFLD Fibrosis Score":"NAFLD Fibrosis Score","NAFLD Fibrosis Score (NFS)":"NAFLD Fibrosis Score (NFS)"},"resultUnits":{},"resultValues":{},"resultNarratives":[{"id":"8c07c847deb0b87be508","toolId":"nafld-fibrosis-score","area":"note","source":"A partir de 65 anos, o corte inferior usado é 0,12 (McPherson 2017).","target":"From 65 years of age, the lower cutoff used is 0,12 (McPherson 2017)."},{"id":"db3b0ead54d32c734597","toolId":"nafld-fibrosis-score","area":"verdict","source":"Resultado indeterminado: complementar com elastografia","target":"Indeterminate result: complement with elastography"},{"id":"def6a6cc82a5b0ee6b0d","toolId":"nafld-fibrosis-score","area":"verdict","source":"Fibrose avançada (F3–F4) improvável","target":"Advanced fibrosis (F3–F4) unlikely"},{"id":"13bd258cf7cc3927cd57","toolId":"nafld-fibrosis-score","area":"verdict","source":"Fibrose avançada (F3–F4) provável","target":"Advanced fibrosis (F3–F4) likely"}]},"shared":{"select":"Select","yes":"Yes","no":"No","optional":"optional","numeric":"Numeric value","range":"range","calculate":"Calculate","calculating":"Calculating…","clear":"Clear","heading":"Calculate with transparency","intro":"Check the population, units and version. The result shows the formula or classification; it does not make an automatic treatment decision.","restricted":"Record available for reference","restrictedNote":"Calculation is suspended in this release. The inventory, outstanding review and sources remain public.","resultNote":"Formula or classification result. Interpretation, care and applicability depend on professional assessment and the selected source.","invalid":"Unable to calculate with these values. Check the conditions of use.","unavailable":"The calculation service is unavailable. Try again.","connection":"Unable to reach the calculation service. Check your connection and try again.","check":"Check the values entered.","fleischner":"Before calculating: reference for incidental pulmonary nodules. The recommendations do not apply to people under 35, lung cancer screening, immunosuppression or known primary cancer.","incompleteAssessment":"A total score cannot be calculated without a complete assessment."},"ui":{"brand":"ELUCENIA · integration code","clinical":"Independent clinical review has not been performed.","conditions":"conditions, sources and permissions","record":"Record and references","code":"JavaScript code","cases":"Reference cases","language":"Language","formula":"Documented formula","edition":"Method edition","limits":"Limits and population","references":"References"}},"es":{"tool":{"id":"nafld-fibrosis-score","title":"Puntuación de fibrosis en EHGNA (NFS)","titleLocale":"es","summary":"Fibrosis avanzada en esteatosis hepática","lead":"Puntuación no invasiva desarrollada para enfermedad hepática grasa no alcohólica (hoy MASLD), que separa baja y alta probabilidad de fibrosis avanzada (F3–F4).","fields":[["idade","Edad","num",{"min":18,"max":100,"unit":"años","ph":"50","unitLocale":"es","displayLocale":"es"}],["imc","IMC","num",{"min":12,"max":80,"step":0.1,"unit":"kg/m²","ph":"30","unitLocale":"es","displayLocale":"es"}],["dm","Glucemia en ayunas alterada o diabetes","radio",{"opts":{"0":"No","1":"Sí"},"unitLocale":"es","displayLocale":"es","optionLocales":{"0":"es","1":"es"}}],["ast","Aspartato aminotransferasa (AST)","num",{"min":1,"max":5000,"unit":"U/L","ph":"40","unitLocale":"es","displayLocale":"es"}],["alt","Alanina aminotransferasa (ALT)","num",{"min":1,"max":5000,"unit":"U/L","ph":"50","unitLocale":"es","displayLocale":"es"}],["plq","Plaquetas","num",{"min":5,"max":1500,"unit":"× 10³/mm³","ph":"200","unitLocale":"es","displayLocale":"es"}],["alb","Albúmina","num",{"min":1,"max":6,"step":0.1,"unit":"g/dL","ph":"4,0","unitLocale":"es","displayLocale":"es"}]],"formula":"<p>NFS = −1,675 + 0,037 × edad + 0,094 × IMC + 1,13 × (glucemia alterada/diabetes: 1) + 0,99 × AST/ALT − 0,013 × plaquetas (10⁹/L) − 0,66 × albúmina (g/dL).</p>","sources":[["Angulo P et al. The NAFLD fibrosis score: a noninvasive system that identifies liver fibrosis in patients with NAFLD. Hepatology, 2007.","https://doi.org/10.1002/hep.21496"],["McPherson S et al. Age as a confounding factor for the accurate non-invasive diagnosis of advanced NAFLD fibrosis. Am J Gastroenterol, 2017.","https://doi.org/10.1038/ajg.2016.453"],["Rinella ME et al. AASLD Practice Guidance on the clinical assessment and management of nonalcoholic fatty liver disease. Hepatology, 2023.","https://doi.org/10.1097/HEP.0000000000000323"]],"methodVersion":"NFS de Angulo et al. (2007), seis variables; la fórmula y los puntos de corte originales se comprobaron en la Tabla 1 de McPherson et al. (2017). Esta implementación utiliza el punto de corte inferior de 0,12 a partir de los 65 años (≥65); el superior sigue siendo 0,676.","methodVersionLocale":"es","implementationVersion":"nafld-fibrosis-score@native-2026-10-05+325fbd4c60c4","limits":"El modelo original se derivó de NAFLD confirmada por biopsia, no de toda la población actualmente denominada MASLD. McPherson (2017) evaluó servicios especializados europeos, excluyó otras hepatopatías y el consumo excesivo de alcohol y encontró un rendimiento bajo en personas de ≤35 años. La Figura 4 y su leyenda difieren en los límites de edad de 35 y 65 años; estas edades exactas no han recibido una adjudicación clínica aquí. El punto de corte inferior de 0,12 para una edad ≥65 es la política declarada de esta implementación. Las plaquetas en ×10³/mm³ equivalen numéricamente a ×10⁹/L; la albúmina debe estar en g/dL. La puntuación se muestra con tres decimales; la clasificación utiliza límites estrictos sin redondearla. Los valores intermedios no son concluyentes; el NFS aislado no confirma F3–F4. No se ha realizado una revisión clínica ni lingüística por profesionales independientes.","limitsLocale":"es","resultLabels":{"NAFLD Fibrosis Score":"Puntuación de fibrosis de la NAFLD","NAFLD Fibrosis Score (NFS)":"Puntuación de fibrosis en EHGNA (NFS)"},"resultUnits":{},"resultValues":{},"resultNarratives":[{"id":"8c07c847deb0b87be508","toolId":"nafld-fibrosis-score","area":"note","source":"A partir de 65 anos, o corte inferior usado é 0,12 (McPherson 2017).","target":"A partir de los 65 años, el punto de corte inferior usado es 0,12 (McPherson 2017)."},{"id":"db3b0ead54d32c734597","toolId":"nafld-fibrosis-score","area":"verdict","source":"Resultado indeterminado: complementar com elastografia","target":"Resultado indeterminado: complementar con elastografía"},{"id":"def6a6cc82a5b0ee6b0d","toolId":"nafld-fibrosis-score","area":"verdict","source":"Fibrose avançada (F3–F4) improvável","target":"Fibrosis avanzada (F3–F4) poco probable"},{"id":"13bd258cf7cc3927cd57","toolId":"nafld-fibrosis-score","area":"verdict","source":"Fibrose avançada (F3–F4) provável","target":"Fibrosis avanzada (F3–F4) probable"}]},"shared":{"select":"Seleccione","yes":"Sí","no":"No","optional":"opcional","numeric":"Valor numérico","range":"intervalo","calculate":"Calcular","calculating":"Calculando…","clear":"Limpiar","heading":"Calcular con transparencia","intro":"Compruebe la población, las unidades y la versión. El resultado presenta la fórmula o clasificación, sin decisión terapéutica automática.","restricted":"Ficha disponible para consulta","restrictedNote":"Cálculo suspendido en esta edición. El inventario, la revisión pendiente y las fuentes siguen siendo públicos.","resultNote":"Resultado de la fórmula o clasificación. La interpretación, la conducta y la aplicabilidad dependen de la evaluación profesional y de la fuente seleccionada.","invalid":"No se puede calcular con estos valores. Compruebe las condiciones de uso.","unavailable":"El servicio de cálculo no está disponible. Inténtelo de nuevo.","connection":"No se pudo consultar el servicio de cálculo. Compruebe la conexión e inténtelo de nuevo.","check":"Compruebe los valores introducidos.","fleischner":"Antes de calcular: referencia para nódulos pulmonares incidentales. Las recomendaciones no se aplican a menores de 35 años, cribado de cáncer de pulmón, inmunosupresión o cáncer primario conocido.","incompleteAssessment":"No se puede calcular el total sin una evaluación completa."},"ui":{"brand":"ELUCENIA · código de integración","clinical":"No se ha realizado una revisión clínica independiente.","conditions":"condiciones, fuentes y permisos","record":"Ficha y referencias","code":"Código JavaScript","cases":"Casos de referencia","language":"Idioma","formula":"Fórmula documentada","edition":"Edición del método","limits":"Límites y población","references":"Referencias"}},"fr":{"tool":{"id":"nafld-fibrosis-score","title":"Score de fibrose NAFLD (NFS)","titleLocale":"fr","summary":"Fibrose avancée dans la stéatose hépatique","lead":"Score non invasif développé pour la stéatose hépatique non alcoolique (aujourd’hui MASLD), séparant faible et forte probabilité de fibrose avancée (F3–F4).","fields":[["idade","Âge","num",{"min":18,"max":100,"unit":"ans","ph":"50","unitLocale":"fr","displayLocale":"fr"}],["imc","IMC","num",{"min":12,"max":80,"step":0.1,"unit":"kg/m²","ph":"30","unitLocale":"fr","displayLocale":"fr"}],["dm","Glycémie à jeun altérée ou diabète","radio",{"opts":{"0":"Non","1":"Oui"},"unitLocale":"fr","displayLocale":"fr","optionLocales":{"0":"fr","1":"fr"}}],["ast","Aspartate aminotransférase (ASAT)","num",{"min":1,"max":5000,"unit":"U/L","ph":"40","unitLocale":"fr","displayLocale":"fr"}],["alt","Alanine aminotransférase (ALAT)","num",{"min":1,"max":5000,"unit":"U/L","ph":"50","unitLocale":"fr","displayLocale":"fr"}],["plq","Plaquettes","num",{"min":5,"max":1500,"unit":"× 10³/mm³","ph":"200","unitLocale":"fr","displayLocale":"fr"}],["alb","Albumine","num",{"min":1,"max":6,"step":0.1,"unit":"g/dL","ph":"4,0","unitLocale":"fr","displayLocale":"fr"}]],"formula":"<p>NFS = −1,675 + 0,037 × âge + 0,094 × IMC + 1,13 × (glycémie altérée/diabète: 1) + 0,99 × AST/ALT − 0,013 × plaquettes (10⁹/L) − 0,66 × albumine (g/dL).</p>","sources":[["Angulo P et al. The NAFLD fibrosis score: a noninvasive system that identifies liver fibrosis in patients with NAFLD. Hepatology, 2007.","https://doi.org/10.1002/hep.21496"],["McPherson S et al. Age as a confounding factor for the accurate non-invasive diagnosis of advanced NAFLD fibrosis. Am J Gastroenterol, 2017.","https://doi.org/10.1038/ajg.2016.453"],["Rinella ME et al. AASLD Practice Guidance on the clinical assessment and management of nonalcoholic fatty liver disease. Hepatology, 2023.","https://doi.org/10.1097/HEP.0000000000000323"]],"methodVersion":"NFS d’Angulo et al. (2007), six variables ; la formule et les seuils d’origine ont été vérifiés dans le Tableau 1 de McPherson et al. (2017). Cette implémentation utilise le seuil inférieur de 0,12 à partir de 65 ans (≥65) ; le seuil supérieur reste de 0,676.","methodVersionLocale":"fr","implementationVersion":"nafld-fibrosis-score@native-2026-10-05+325fbd4c60c4","limits":"Le modèle initial a été établi chez des personnes atteintes de NAFLD confirmée par biopsie, et non dans toutes les populations aujourd’hui désignées par MASLD. McPherson (2017) a évalué des services spécialisés européens, exclu les autres hépatopathies et la consommation excessive d’alcool, et constaté une faible performance chez les personnes âgées de ≤35 ans. La Figure 4 et sa légende diffèrent aux limites d’âge de 35 et 65 ans ; ces âges exacts n’ont pas fait l’objet d’un arbitrage clinique ici. Le seuil inférieur de 0,12 pour un âge ≥65 est la règle déclarée de cette implémentation. Les plaquettes en ×10³/mm³ sont numériquement équivalentes à ×10⁹/L ; l’albumine doit être exprimée en g/dL. Le score est affiché avec trois décimales ; la classification utilise des seuils stricts sans arrondir le score. Les valeurs intermédiaires sont non concluantes ; le NFS seul ne confirme pas F3–F4. Aucune revue clinique ou linguistique par des professionnels indépendants n’a été effectuée.","limitsLocale":"fr","resultLabels":{"NAFLD Fibrosis Score":"Score de fibrose de la NAFLD","NAFLD Fibrosis Score (NFS)":"Score de fibrose NAFLD (NFS)"},"resultUnits":{},"resultValues":{},"resultNarratives":[{"id":"8c07c847deb0b87be508","toolId":"nafld-fibrosis-score","area":"note","source":"A partir de 65 anos, o corte inferior usado é 0,12 (McPherson 2017).","target":"À partir de 65 ans, le seuil inférieur utilisé est 0,12 (McPherson 2017)."},{"id":"db3b0ead54d32c734597","toolId":"nafld-fibrosis-score","area":"verdict","source":"Resultado indeterminado: complementar com elastografia","target":"Résultat indéterminé : compléter par une élastographie"},{"id":"def6a6cc82a5b0ee6b0d","toolId":"nafld-fibrosis-score","area":"verdict","source":"Fibrose avançada (F3–F4) improvável","target":"Fibrose avancée (F3–F4) peu probable"},{"id":"13bd258cf7cc3927cd57","toolId":"nafld-fibrosis-score","area":"verdict","source":"Fibrose avançada (F3–F4) provável","target":"Fibrose avancée (F3–F4) probable"}]},"shared":{"select":"Sélectionner","yes":"Oui","no":"Non","optional":"facultatif","numeric":"Valeur numérique","range":"intervalle","calculate":"Calculer","calculating":"Calcul en cours…","clear":"Effacer","heading":"Calculer en toute transparence","intro":"Vérifiez la population, les unités et la version. Le résultat présente la formule ou la classification, sans décision thérapeutique automatique.","restricted":"Fiche disponible à la consultation","restrictedNote":"Calcul suspendu dans cette version. L’inventaire, la révision en attente et les sources restent publics.","resultNote":"Résultat de la formule ou de la classification. L’interprétation, la conduite et l’applicabilité dépendent de l’évaluation professionnelle et de la source sélectionnée.","invalid":"Calcul impossible avec ces valeurs. Vérifiez les conditions d’utilisation.","unavailable":"Le service de calcul est indisponible. Réessayez.","connection":"Impossible de joindre le service de calcul. Vérifiez la connexion et réessayez.","check":"Vérifiez les valeurs saisies.","fleischner":"Avant le calcul : référence pour les nodules pulmonaires fortuits. Les recommandations ne s’appliquent pas aux personnes de moins de 35 ans, au dépistage du cancer du poumon, à l’immunosuppression ou à un cancer primitif connu.","incompleteAssessment":"Le total ne peut pas être calculé sans évaluation complète."},"ui":{"brand":"ELUCENIA · code d’intégration","clinical":"Aucune révision clinique indépendante n’a été effectuée.","conditions":"conditions, sources et autorisations","record":"Fiche et références","code":"Code JavaScript","cases":"Cas de référence","language":"Langue","formula":"Formule documentée","edition":"Édition de la méthode","limits":"Limites et population","references":"Références"}},"de":{"tool":{"id":"nafld-fibrosis-score","title":"NAFLD-Fibrose-Score (NFS)","titleLocale":"de","summary":"Fortgeschrittene Fibrose bei hepatischer Steatose","lead":"Nichtinvasiver Score für nichtalkoholische Fettlebererkrankung (heute MASLD), der niedrige und hohe Wahrscheinlichkeit fortgeschrittener Fibrose (F3–F4) trennt.","fields":[["idade","Alter","num",{"min":18,"max":100,"unit":"Jahre","ph":"50","unitLocale":"de","displayLocale":"de"}],["imc","BMI","num",{"min":12,"max":80,"step":0.1,"unit":"kg/m²","ph":"30","unitLocale":"de","displayLocale":"de"}],["dm","Gestörte Nüchternglukose oder Diabetes","radio",{"opts":{"0":"Nein","1":"Ja"},"unitLocale":"de","displayLocale":"de","optionLocales":{"0":"de","1":"de"}}],["ast","Aspartat-Aminotransferase (AST/GOT)","num",{"min":1,"max":5000,"unit":"U/L","ph":"40","unitLocale":"de","displayLocale":"de"}],["alt","Alanin-Aminotransferase (ALT/GPT)","num",{"min":1,"max":5000,"unit":"U/L","ph":"50","unitLocale":"de","displayLocale":"de"}],["plq","Thrombozyten","num",{"min":5,"max":1500,"unit":"× 10³/mm³","ph":"200","unitLocale":"de","displayLocale":"de"}],["alb","Albumin","num",{"min":1,"max":6,"step":0.1,"unit":"g/dL","ph":"4,0","unitLocale":"de","displayLocale":"de"}]],"formula":"<p>NFS = −1,675 + 0,037 × Alter + 0,094 × BMI + 1,13 × (gestörte Glykämie/Diabetes: 1) + 0,99 × AST/ALT − 0,013 × Thrombozyten (10⁹/L) − 0,66 × Albumin (g/dL).</p>","sources":[["Angulo P et al. The NAFLD fibrosis score: a noninvasive system that identifies liver fibrosis in patients with NAFLD. Hepatology, 2007.","https://doi.org/10.1002/hep.21496"],["McPherson S et al. Age as a confounding factor for the accurate non-invasive diagnosis of advanced NAFLD fibrosis. Am J Gastroenterol, 2017.","https://doi.org/10.1038/ajg.2016.453"],["Rinella ME et al. AASLD Practice Guidance on the clinical assessment and management of nonalcoholic fatty liver disease. Hepatology, 2023.","https://doi.org/10.1097/HEP.0000000000000323"]],"methodVersion":"NFS nach Angulo et al. (2007), sechs Variablen; die ursprüngliche Formel und die Grenzwerte wurden anhand von Tabelle 1 bei McPherson et al. (2017) überprüft. Diese Implementierung verwendet ab einem Alter von 65 Jahren (≥65) den unteren Grenzwert 0,12; der obere Grenzwert bleibt 0,676.","methodVersionLocale":"de","implementationVersion":"nafld-fibrosis-score@native-2026-10-05+325fbd4c60c4","limits":"Das ursprüngliche Modell wurde bei biopsiebestätigter NAFLD entwickelt, nicht für sämtliche heute als MASLD bezeichneten Populationen. McPherson (2017) untersuchte europäische Spezialambulanzen, schloss andere Lebererkrankungen und übermäßigen Alkoholkonsum aus und stellte bei Personen im Alter von ≤35 Jahren eine geringe Aussagekraft fest. Abbildung 4 und ihre Legende unterscheiden sich an den Altersgrenzen 35 und 65 Jahre; diese exakten Alterswerte wurden hier nicht klinisch beurteilt. Der untere Grenzwert 0,12 ab einem Alter von ≥65 ist die erklärte Regel dieser Implementierung. Thrombozyten in ×10³/mm³ entsprechen zahlenmäßig ×10⁹/L; Albumin muss in g/dL angegeben werden. Der Score wird mit drei Dezimalstellen angezeigt; die Klassifikation verwendet strikte Grenzwerte ohne Rundung des Scores. Zwischenwerte sind nicht eindeutig; der NFS allein bestätigt F3–F4 nicht. Eine klinische oder sprachliche Prüfung durch unabhängige Fachleute wurde nicht durchgeführt.","limitsLocale":"de","resultLabels":{"NAFLD Fibrosis Score":"NAFLD-Fibrose-Score","NAFLD Fibrosis Score (NFS)":"NAFLD-Fibrose-Score (NFS)"},"resultUnits":{},"resultValues":{},"resultNarratives":[{"id":"8c07c847deb0b87be508","toolId":"nafld-fibrosis-score","area":"note","source":"A partir de 65 anos, o corte inferior usado é 0,12 (McPherson 2017).","target":"Ab 65 Jahren beträgt der verwendete untere Grenzwert 0,12 (McPherson 2017)."},{"id":"db3b0ead54d32c734597","toolId":"nafld-fibrosis-score","area":"verdict","source":"Resultado indeterminado: complementar com elastografia","target":"Unbestimmtes Ergebnis: durch Elastographie ergänzen"},{"id":"def6a6cc82a5b0ee6b0d","toolId":"nafld-fibrosis-score","area":"verdict","source":"Fibrose avançada (F3–F4) improvável","target":"Fortgeschrittene Fibrose (F3–F4) unwahrscheinlich"},{"id":"13bd258cf7cc3927cd57","toolId":"nafld-fibrosis-score","area":"verdict","source":"Fibrose avançada (F3–F4) provável","target":"Fortgeschrittene Fibrose (F3–F4) wahrscheinlich"}]},"shared":{"select":"Auswählen","yes":"Ja","no":"Nein","optional":"optional","numeric":"Numerischer Wert","range":"Bereich","calculate":"Berechnen","calculating":"Berechnung läuft…","clear":"Löschen","heading":"Transparent berechnen","intro":"Prüfen Sie Population, Einheiten und Version. Das Ergebnis zeigt die Formel oder Klassifikation, ohne automatisch eine Therapieentscheidung zu treffen.","restricted":"Eintrag zur Einsicht verfügbar","restrictedNote":"Die Berechnung ist in dieser Version ausgesetzt. Inventar, ausstehende Prüfung und Quellen bleiben öffentlich.","resultNote":"Ergebnis der Formel oder Klassifikation. Interpretation, Vorgehen und Anwendbarkeit hängen von der fachlichen Beurteilung und der ausgewählten Quelle ab.","invalid":"Berechnung mit diesen Werten nicht möglich. Prüfen Sie die Nutzungsbedingungen.","unavailable":"Der Berechnungsdienst ist nicht verfügbar. Versuchen Sie es erneut.","connection":"Der Berechnungsdienst ist nicht erreichbar. Prüfen Sie die Verbindung und versuchen Sie es erneut.","check":"Prüfen Sie die eingegebenen Werte.","fleischner":"Vor der Berechnung: Referenz für zufällig entdeckte Lungenrundherde. Die Empfehlungen gelten nicht für Personen unter 35 Jahren, Lungenkrebs-Screening, Immunsuppression oder bekannten Primärkrebs.","incompleteAssessment":"Ohne vollständige Untersuchung lässt sich kein Gesamtscore berechnen."},"ui":{"brand":"ELUCENIA · Integrationscode","clinical":"Eine unabhängige klinische Prüfung wurde nicht durchgeführt.","conditions":"Bedingungen, Quellen und Berechtigungen","record":"Eintrag und Referenzen","code":"JavaScript-Code","cases":"Referenzfälle","language":"Sprache","formula":"Dokumentierte Formel","edition":"Fassung der Methode","limits":"Grenzen und Population","references":"Referenzen"}},"it":{"tool":{"id":"nafld-fibrosis-score","title":"Punteggio di fibrosi NAFLD (NFS)","titleLocale":"it","summary":"Fibrosi avanzata nella steatosi epatica","lead":"Score non invasivo per la steatosi epatica non alcolica (oggi MASLD), che distingue bassa e alta probabilità di fibrosi avanzata (F3–F4).","fields":[["idade","Età","num",{"min":18,"max":100,"unit":"anni","ph":"50","unitLocale":"it","displayLocale":"it"}],["imc","IMC","num",{"min":12,"max":80,"step":0.1,"unit":"kg/m²","ph":"30","unitLocale":"it","displayLocale":"it"}],["dm","Alterata glicemia a digiuno o diabete","radio",{"opts":{"0":"No","1":"Sì"},"unitLocale":"it","displayLocale":"it","optionLocales":{"0":"it","1":"it"}}],["ast","Aspartato aminotransferasi (AST)","num",{"min":1,"max":5000,"unit":"U/L","ph":"40","unitLocale":"it","displayLocale":"it"}],["alt","Alanina aminotransferasi (ALT)","num",{"min":1,"max":5000,"unit":"U/L","ph":"50","unitLocale":"it","displayLocale":"it"}],["plq","Piastrine","num",{"min":5,"max":1500,"unit":"× 10³/mm³","ph":"200","unitLocale":"it","displayLocale":"it"}],["alb","Albumina","num",{"min":1,"max":6,"step":0.1,"unit":"g/dL","ph":"4,0","unitLocale":"it","displayLocale":"it"}]],"formula":"<p>NFS = −1,675 + 0,037 × età + 0,094 × IMC + 1,13 × (glicemia alterata/diabete: 1) + 0,99 × AST/ALT − 0,013 × piastrine (10⁹/L) − 0,66 × albumina (g/dL).</p>","sources":[["Angulo P et al. The NAFLD fibrosis score: a noninvasive system that identifies liver fibrosis in patients with NAFLD. Hepatology, 2007.","https://doi.org/10.1002/hep.21496"],["McPherson S et al. Age as a confounding factor for the accurate non-invasive diagnosis of advanced NAFLD fibrosis. Am J Gastroenterol, 2017.","https://doi.org/10.1038/ajg.2016.453"],["Rinella ME et al. AASLD Practice Guidance on the clinical assessment and management of nonalcoholic fatty liver disease. Hepatology, 2023.","https://doi.org/10.1097/HEP.0000000000000323"]],"methodVersion":"NFS di Angulo et al. (2007), sei variabili; formula e soglie originali verificate nella Tabella 1 di McPherson et al. (2017). Questa implementazione usa la soglia inferiore di 0,12 dai 65 anni di età (≥65); la soglia superiore resta 0,676.","methodVersionLocale":"it","implementationVersion":"nafld-fibrosis-score@native-2026-10-05+325fbd4c60c4","limits":"Il modello originale è stato derivato da NAFLD confermata mediante biopsia, non da tutte le popolazioni oggi definite MASLD. McPherson (2017) ha valutato centri specialistici europei, ha escluso altre epatopatie e il consumo eccessivo di alcol e ha riscontrato prestazioni scarse nelle persone di età ≤35 anni. La Figura 4 e la sua didascalia differiscono ai limiti di età di 35 e 65 anni; queste età esatte non sono state oggetto di un giudizio clinico in questa sede. La soglia inferiore di 0,12 per età ≥65 è la regola dichiarata di questa implementazione. Le piastrine in ×10³/mm³ equivalgono numericamente a ×10⁹/L; l’albumina deve essere espressa in g/dL. Il punteggio viene mostrato con tre decimali; la classificazione usa soglie rigorose senza arrotondare il punteggio. I valori intermedi non sono conclusivi; il solo NFS non conferma F3–F4. Non è stata effettuata una revisione clinica o linguistica da parte di professionisti indipendenti.","limitsLocale":"it","resultLabels":{"NAFLD Fibrosis Score":"Punteggio di fibrosi della NAFLD","NAFLD Fibrosis Score (NFS)":"Punteggio di fibrosi NAFLD (NFS)"},"resultUnits":{},"resultValues":{},"resultNarratives":[{"id":"8c07c847deb0b87be508","toolId":"nafld-fibrosis-score","area":"note","source":"A partir de 65 anos, o corte inferior usado é 0,12 (McPherson 2017).","target":"A partire da 65 anni, il cut-off inferiore utilizzato è 0,12 (McPherson 2017)."},{"id":"db3b0ead54d32c734597","toolId":"nafld-fibrosis-score","area":"verdict","source":"Resultado indeterminado: complementar com elastografia","target":"Risultato indeterminato: integrare con elastografia"},{"id":"def6a6cc82a5b0ee6b0d","toolId":"nafld-fibrosis-score","area":"verdict","source":"Fibrose avançada (F3–F4) improvável","target":"Fibrosi avanzata (F3–F4) improbabile"},{"id":"13bd258cf7cc3927cd57","toolId":"nafld-fibrosis-score","area":"verdict","source":"Fibrose avançada (F3–F4) provável","target":"Fibrosi avanzata (F3–F4) probabile"}]},"shared":{"select":"Seleziona","yes":"Sì","no":"No","optional":"facoltativo","numeric":"Valore numerico","range":"intervallo","calculate":"Calcola","calculating":"Calcolo in corso…","clear":"Cancella","heading":"Calcolare con trasparenza","intro":"Verifica popolazione, unità e versione. Il risultato mostra la formula o la classificazione, senza una decisione terapeutica automatica.","restricted":"Scheda disponibile per consultazione","restrictedNote":"Calcolo sospeso in questa versione. Inventario, revisione in sospeso e fonti rimangono pubblici.","resultNote":"Risultato della formula o classificazione. Interpretazione, condotta e applicabilità dipendono dalla valutazione professionale e dalla fonte selezionata.","invalid":"Impossibile calcolare con questi valori. Verifica le condizioni d’uso.","unavailable":"Il servizio di calcolo non è disponibile. Riprova.","connection":"Impossibile contattare il servizio di calcolo. Verifica la connessione e riprova.","check":"Verifica i valori inseriti.","fleischner":"Prima del calcolo: riferimento per noduli polmonari incidentali. Le raccomandazioni non si applicano a persone di età inferiore a 35 anni, screening del cancro del polmone, immunosoppressione o tumore primario noto.","incompleteAssessment":"Il totale non può essere calcolato senza una valutazione completa."},"ui":{"brand":"ELUCENIA · codice di integrazione","clinical":"Non è stata effettuata una revisione clinica indipendente.","conditions":"condizioni, fonti e autorizzazioni","record":"Scheda e riferimenti","code":"Codice JavaScript","cases":"Casi di riferimento","language":"Lingua","formula":"Formula documentata","edition":"Edizione del metodo","limits":"Limiti e popolazione","references":"Riferimenti"}},"ar":{"tool":{"id":"nafld-fibrosis-score","title":"درجة تليف الكبد في NAFLD (NFS)","titleLocale":"ar","summary":"التليف المتقدم في تشحم الكبد","lead":"مقياس غير باضع طُوّر لمرض الكبد الدهني غير الكحولي (اليوم MASLD)، يميز الاحتمال المنخفض والمرتفع للتليف المتقدم (F3–F4).","fields":[["idade","العمر","num",{"min":18,"max":100,"unit":"سنوات","ph":"٥٠","unitLocale":"ar","displayLocale":"ar"}],["imc","مؤشر كتلة الجسم (BMI)","num",{"min":12,"max":80,"step":0.1,"unit":"kg/m²","ph":"٣٠","unitLocale":"ar","displayLocale":"ar"}],["dm","اضطراب سكر الدم الصيامي أو داء السكري","radio",{"opts":{"0":"لا","1":"نعم"},"unitLocale":"ar","displayLocale":"ar","optionLocales":{"0":"ar","1":"ar"}}],["ast","AST","num",{"min":1,"max":5000,"unit":"U/L","ph":"٤٠","unitLocale":"ar","displayLocale":"ar"}],["alt","ALT","num",{"min":1,"max":5000,"unit":"U/L","ph":"٥٠","unitLocale":"ar","displayLocale":"ar"}],["plq","الصفائح الدموية","num",{"min":5,"max":1500,"unit":"× 10³/mm³","ph":"٢٠٠","unitLocale":"ar","displayLocale":"ar"}],["alb","الألبومين","num",{"min":1,"max":6,"step":0.1,"unit":"g/dL","ph":"٤٫٠","unitLocale":"ar","displayLocale":"ar"}]],"formula":"<p>NFS = −1.675 + 0.037 × العمر + 0.094 × BMI + 1.13 × (اضطراب سكر الدم/السكري: 1) + 0.99 × AST/ALT − 0.013 × الصفائح (10⁹/L) − 0.66 × الألبومين (g/dL).</p>","sources":[["Angulo P et al. The NAFLD fibrosis score: a noninvasive system that identifies liver fibrosis in patients with NAFLD. Hepatology, 2007.","https://doi.org/10.1002/hep.21496"],["McPherson S et al. Age as a confounding factor for the accurate non-invasive diagnosis of advanced NAFLD fibrosis. Am J Gastroenterol, 2017.","https://doi.org/10.1038/ajg.2016.453"],["Rinella ME et al. AASLD Practice Guidance on the clinical assessment and management of nonalcoholic fatty liver disease. Hepatology, 2023.","https://doi.org/10.1097/HEP.0000000000000323"]],"methodVersion":"درجة NFS وفق Angulo وزملائه (2007)، بستة متغيرات؛ روجعت المعادلة والحدود الأصلية في الجدول ١ من McPherson وزملائه (2017). تستخدم هذه النسخة الحد الأدنى ٠٫١٢ عند عمر ≥٦٥ سنة؛ ويظل الحد الأعلى ٠٫٦٧٦.","methodVersionLocale":"ar","implementationVersion":"nafld-fibrosis-score@native-2026-10-05+325fbd4c60c4","limits":"اشتُق النموذج الأصلي من حالات NAFLD المؤكدة بالخزعة، لا من جميع الفئات التي تسمى حاليًا MASLD. قيّم McPherson (2017) عيادات أوروبية متخصصة، واستبعد أمراض الكبد الأخرى والإفراط في تناول الكحول، ووجد أداءً ضعيفًا لدى من أعمارهم ≤٣٥ سنة. يختلف الشكل ٤ وتعليقه عند حدّي العمر ٣٥ و٦٥ سنة؛ ولم تُحسم دلالة هذين العمرين بالضبط سريريًا هنا. الحد الأدنى ٠٫١٢ عند عمر ≥٦٥ هو السياسة المعلنة لهذه النسخة. الصفائح بوحدة ×10³/mm³ تعادل عدديًا ×10⁹/L؛ ويجب أن يكون الألبومين بوحدة g/dL. تُعرض الدرجة بثلاث منازل عشرية؛ ويستخدم التصنيف حدودًا صارمة دون تقريب الدرجة. القيم المتوسطة غير حاسمة؛ ولا تؤكد درجة NFS وحدها F3–F4. لم تُجرَ مراجعة سريرية أو لغوية من اختصاصيين مستقلين.","limitsLocale":"ar","resultLabels":{"NAFLD Fibrosis Score":"درجة تليف الكبد في NAFLD","NAFLD Fibrosis Score (NFS)":"درجة تليف الكبد في NAFLD (NFS)"},"resultUnits":{},"resultValues":{},"resultNarratives":[{"id":"8c07c847deb0b87be508","toolId":"nafld-fibrosis-score","area":"note","source":"A partir de 65 anos, o corte inferior usado é 0,12 (McPherson 2017).","target":"ابتداءً من سن 65 عامًا، تكون العتبة الدنيا المستخدمة 0,12 (McPherson 2017)."},{"id":"db3b0ead54d32c734597","toolId":"nafld-fibrosis-score","area":"verdict","source":"Resultado indeterminado: complementar com elastografia","target":"نتيجة غير حاسمة: استكملها بالتصوير المرن"},{"id":"def6a6cc82a5b0ee6b0d","toolId":"nafld-fibrosis-score","area":"verdict","source":"Fibrose avançada (F3–F4) improvável","target":"التليف المتقدم (F3–F4) غير مرجح"},{"id":"13bd258cf7cc3927cd57","toolId":"nafld-fibrosis-score","area":"verdict","source":"Fibrose avançada (F3–F4) provável","target":"التليف المتقدم (F3–F4) مرجح"}]},"shared":{"select":"اختر","yes":"نعم","no":"لا","optional":"اختياري","numeric":"قيمة رقمية","range":"النطاق","calculate":"احسب","calculating":"جارٍ الحساب…","clear":"مسح","heading":"حساب بشفافية","intro":"تحقق من الفئة السكانية والوحدات والإصدار. تعرض النتيجة المعادلة أو التصنيف دون اتخاذ قرار علاجي تلقائي.","restricted":"السجل متاح للاطلاع","restrictedNote":"الحساب معلّق في هذا الإصدار. يظل السجل والمراجعة المعلّقة والمصادر متاحة للعامة.","resultNote":"نتيجة المعادلة أو التصنيف. يعتمد التفسير والتصرف ومدى الانطباق على التقييم المهني والمصدر المحدد.","invalid":"تعذر الحساب بهذه القيم. تحقق من شروط الاستخدام.","unavailable":"خدمة الحساب غير متاحة. حاول مرة أخرى.","connection":"تعذر الاتصال بخدمة الحساب. تحقق من الاتصال وحاول مرة أخرى.","check":"تحقق من القيم المدخلة.","fleischner":"قبل الحساب: مرجع للعقيدات الرئوية المكتشفة عرضًا. لا تنطبق التوصيات على من هم دون 35 عامًا، أو فحص سرطان الرئة، أو كبت المناعة، أو وجود سرطان أولي معروف.","incompleteAssessment":"لا يمكن حساب المجموع دون تقييم مكتمل."},"ui":{"brand":"ELUCENIA · شيفرة التكامل","clinical":"لم تُجرَ مراجعة سريرية مستقلة.","conditions":"الشروط والمصادر والأذونات","record":"السجل والمراجع","code":"شيفرة JavaScript","cases":"حالات مرجعية","language":"اللغة","formula":"المعادلة الموثقة","edition":"إصدار الطريقة","limits":"الحدود والفئة السكانية","references":"المراجع"}},"zh":{"tool":{"id":"nafld-fibrosis-score","title":"NAFLD 肝纤维化评分（NFS）","titleLocale":"zh","summary":"肝脂肪变中的进展期纤维化","lead":"为非酒精性脂肪性肝病（现称MASLD）开发的无创评分，区分进展期纤维化（F3–F4）的低概率与高概率。","fields":[["idade","年龄","num",{"min":18,"max":100,"unit":"年","ph":"50","unitLocale":"zh","displayLocale":"zh"}],["imc","体重指数（BMI）","num",{"min":12,"max":80,"step":0.1,"unit":"kg/m²","ph":"30","unitLocale":"zh","displayLocale":"zh"}],["dm","空腹血糖异常或糖尿病","radio",{"opts":{"0":"否","1":"是"},"unitLocale":"zh","displayLocale":"zh","optionLocales":{"0":"zh","1":"zh"}}],["ast","AST","num",{"min":1,"max":5000,"unit":"U/L","ph":"40","unitLocale":"zh","displayLocale":"zh"}],["alt","ALT","num",{"min":1,"max":5000,"unit":"U/L","ph":"50","unitLocale":"zh","displayLocale":"zh"}],["plq","血小板","num",{"min":5,"max":1500,"unit":"× 10³/mm³","ph":"200","unitLocale":"zh","displayLocale":"zh"}],["alb","白蛋白","num",{"min":1,"max":6,"step":0.1,"unit":"g/dL","ph":"4.0","unitLocale":"zh","displayLocale":"zh"}]],"formula":"<p>NFS = −1.675 + 0.037 × 年龄 + 0.094 × BMI + 1.13 × (血糖异常/糖尿病: 1) + 0.99 × AST/ALT − 0.013 × 血小板 (10⁹/L) − 0.66 × 白蛋白 (g/dL).</p>","sources":[["Angulo P et al. The NAFLD fibrosis score: a noninvasive system that identifies liver fibrosis in patients with NAFLD. Hepatology, 2007.","https://doi.org/10.1002/hep.21496"],["McPherson S et al. Age as a confounding factor for the accurate non-invasive diagnosis of advanced NAFLD fibrosis. Am J Gastroenterol, 2017.","https://doi.org/10.1038/ajg.2016.453"],["Rinella ME et al. AASLD Practice Guidance on the clinical assessment and management of nonalcoholic fatty liver disease. Hepatology, 2023.","https://doi.org/10.1097/HEP.0000000000000323"]],"methodVersion":"Angulo等（2007）的NFS，包含六个变量；原始公式和界值已按McPherson等（2017）的表1核对。本实现对年龄≥65岁者采用下限0.12；上限仍为0.676。","methodVersionLocale":"zh","implementationVersion":"nafld-fibrosis-score@native-2026-10-05+325fbd4c60c4","limits":"原模型基于活检确诊的NAFLD建立，并不代表目前称为MASLD的所有人群。McPherson（2017）评估了欧洲专科诊疗机构，排除了其他肝病和过量饮酒者，并发现≤35岁人群的判别表现较差。图4与图注在35岁和65岁边界处存在不一致；本平台未对这两个确切年龄作临床裁定。年龄≥65岁时采用下限0.12是本实现声明的规则。血小板单位×10³/mm³在数值上等同于×10⁹/L；白蛋白必须使用g/dL。分值显示三位小数；分类依据严格界值，不先对分值进行舍入。中间值不能得出明确结论；单独的NFS不能确认F3–F4。尚未由独立专业人员进行临床和语言审核。","limitsLocale":"zh","resultLabels":{"NAFLD Fibrosis Score":"NAFLD 肝纤维化评分","NAFLD Fibrosis Score (NFS)":"NAFLD 肝纤维化评分（NFS）"},"resultUnits":{},"resultValues":{},"resultNarratives":[{"id":"8c07c847deb0b87be508","toolId":"nafld-fibrosis-score","area":"note","source":"A partir de 65 anos, o corte inferior usado é 0,12 (McPherson 2017).","target":"从65岁起，所使用的下限切点为 0,12（McPherson 2017）。"},{"id":"db3b0ead54d32c734597","toolId":"nafld-fibrosis-score","area":"verdict","source":"Resultado indeterminado: complementar com elastografia","target":"结果不确定：请结合弹性成像补充评估"},{"id":"def6a6cc82a5b0ee6b0d","toolId":"nafld-fibrosis-score","area":"verdict","source":"Fibrose avançada (F3–F4) improvável","target":"进展期纤维化（F3–F4）不太可能"},{"id":"13bd258cf7cc3927cd57","toolId":"nafld-fibrosis-score","area":"verdict","source":"Fibrose avançada (F3–F4) provável","target":"进展期纤维化（F3–F4）可能"}]},"shared":{"select":"请选择","yes":"是","no":"否","optional":"选填","numeric":"数值","range":"范围","calculate":"计算","calculating":"计算中…","clear":"清除","heading":"透明计算","intro":"请核对适用人群、单位和版本。结果展示公式或分类，不自动作出治疗决定。","restricted":"可查阅工具记录","restrictedNote":"本版本暂停计算。清单、待审事项和来源仍公开。","resultNote":"公式或分类结果。解释、处理及适用性须结合专业评估和所选来源。","invalid":"无法使用这些数值计算。请核对使用条件。","unavailable":"计算服务暂不可用。请重试。","connection":"无法连接计算服务。请检查网络后重试。","check":"请检查输入值。","fleischner":"计算前：此参考适用于偶然发现的肺结节。建议不适用于35岁以下人群、肺癌筛查、免疫抑制或已知原发性癌症患者。","incompleteAssessment":"未完成评估，无法计算总分。"},"ui":{"brand":"ELUCENIA · 集成代码","clinical":"尚未开展独立临床审查。","conditions":"条件、来源与许可","record":"记录与参考文献","code":"JavaScript代码","cases":"参考案例","language":"语言","formula":"已记录的公式","edition":"方法版本","limits":"限制与适用人群","references":"参考文献"}},"ja":{"tool":{"id":"nafld-fibrosis-score","title":"NAFLD線維化スコア（NFS）","titleLocale":"ja","summary":"脂肪肝の進行線維化","lead":"非アルコール性脂肪肝疾患（現在MASLD）用の非侵襲的スコアで、進行線維化（F3–F4）の低確率と高確率を区別します。","fields":[["idade","年齢","num",{"min":18,"max":100,"unit":"年","ph":"50","unitLocale":"ja","displayLocale":"ja"}],["imc","体格指数（BMI）","num",{"min":12,"max":80,"step":0.1,"unit":"kg/m²","ph":"30","unitLocale":"ja","displayLocale":"ja"}],["dm","空腹時血糖異常または糖尿病","radio",{"opts":{"0":"いいえ","1":"はい"},"unitLocale":"ja","displayLocale":"ja","optionLocales":{"0":"ja","1":"ja"}}],["ast","AST","num",{"min":1,"max":5000,"unit":"U/L","ph":"40","unitLocale":"ja","displayLocale":"ja"}],["alt","ALT","num",{"min":1,"max":5000,"unit":"U/L","ph":"50","unitLocale":"ja","displayLocale":"ja"}],["plq","血小板","num",{"min":5,"max":1500,"unit":"× 10³/mm³","ph":"200","unitLocale":"ja","displayLocale":"ja"}],["alb","アルブミン","num",{"min":1,"max":6,"step":0.1,"unit":"g/dL","ph":"4.0","unitLocale":"ja","displayLocale":"ja"}]],"formula":"<p>NFS = −1.675 + 0.037 × 年齢 + 0.094 × BMI + 1.13 × (血糖異常/糖尿病: 1) + 0.99 × AST/ALT − 0.013 × 血小板 (10⁹/L) − 0.66 × アルブミン (g/dL).</p>","sources":[["Angulo P et al. The NAFLD fibrosis score: a noninvasive system that identifies liver fibrosis in patients with NAFLD. Hepatology, 2007.","https://doi.org/10.1002/hep.21496"],["McPherson S et al. Age as a confounding factor for the accurate non-invasive diagnosis of advanced NAFLD fibrosis. Am J Gastroenterol, 2017.","https://doi.org/10.1038/ajg.2016.453"],["Rinella ME et al. AASLD Practice Guidance on the clinical assessment and management of nonalcoholic fatty liver disease. Hepatology, 2023.","https://doi.org/10.1097/HEP.0000000000000323"]],"methodVersion":"Anguloら（2007）のNFSは六つの変数を用い、元の式とカットオフ値はMcPhersonら（2017）の表1で照合した。本実装では65歳以上（≥65）の下限を0.12とし、上限は0.676のままとしている。","methodVersionLocale":"ja","implementationVersion":"nafld-fibrosis-score@native-2026-10-05+325fbd4c60c4","limits":"元のモデルは生検で確定したNAFLDを対象に作成されており、現在MASLDと呼ばれるすべての集団を対象とするものではない。McPherson（2017）は欧州の専門診療施設を評価し、他の肝疾患と過剰な飲酒を除外し、35歳以下（≤35）では判別性能が低いことを報告した。図4と図注には35歳と65歳の境界で相違があり、これらの年齢ちょうどの扱いについて本実装では臨床的な裁定を行っていない。65歳以上（≥65）で下限0.12を使用するのは本実装で明示した規則である。血小板数の×10³/mm³は×10⁹/Lと数値的に等価であり、アルブミンはg/dLで入力する。スコアは小数点以下三桁で表示し、分類はスコアを丸めずに厳密なカットオフ値を用いる。中間値は確定的な判断を示さず、NFS単独ではF3–F4を確定できない。独立した専門家による臨床・言語レビューは未実施である。","limitsLocale":"ja","resultLabels":{"NAFLD Fibrosis Score":"NAFLD線維化スコア","NAFLD Fibrosis Score (NFS)":"NAFLD線維化スコア（NFS）"},"resultUnits":{},"resultValues":{},"resultNarratives":[{"id":"8c07c847deb0b87be508","toolId":"nafld-fibrosis-score","area":"note","source":"A partir de 65 anos, o corte inferior usado é 0,12 (McPherson 2017).","target":"65歳以上では、使用する下限カットオフは 0,12 である（McPherson 2017）。"},{"id":"db3b0ead54d32c734597","toolId":"nafld-fibrosis-score","area":"verdict","source":"Resultado indeterminado: complementar com elastografia","target":"判定不能：エラストグラフィを追加する"},{"id":"def6a6cc82a5b0ee6b0d","toolId":"nafld-fibrosis-score","area":"verdict","source":"Fibrose avançada (F3–F4) improvável","target":"進行した線維化（F3–F4）の可能性は低い"},{"id":"13bd258cf7cc3927cd57","toolId":"nafld-fibrosis-score","area":"verdict","source":"Fibrose avançada (F3–F4) provável","target":"進行した線維化（F3–F4）の可能性が高い"}]},"shared":{"select":"選択","yes":"はい","no":"いいえ","optional":"任意","numeric":"数値","range":"範囲","calculate":"計算","calculating":"計算中…","clear":"クリア","heading":"根拠を明示して計算","intro":"対象集団、単位、版を確認してください。結果は式または分類を示すもので、治療方針を自動決定しません。","restricted":"記録を参照できます","restrictedNote":"この版では計算を停止しています。目録、未完了の審査、出典は公開されています。","resultNote":"式または分類の結果です。解釈、対応、適用可能性は専門家による評価と選択した出典に依存します。","invalid":"この値では計算できません。使用条件を確認してください。","unavailable":"計算サービスを利用できません。再試行してください。","connection":"計算サービスに接続できません。接続を確認して再試行してください。","check":"入力値を確認してください。","fleischner":"計算前：偶発的に発見された肺結節に関する参考です。35歳未満、肺がん検診、免疫抑制、既知の原発がんには推奨を適用できません。","incompleteAssessment":"評価が完了していないため合計を計算できません。"},"ui":{"brand":"ELUCENIA · 連携コード","clinical":"独立した臨床レビューは実施されていません。","conditions":"条件・出典・許諾","record":"記録・参考文献","code":"JavaScriptコード","cases":"参照ケース","language":"言語","formula":"記載された計算式","edition":"方法の版","limits":"限界・対象集団","references":"参考文献"}},"hi":{"tool":{"id":"nafld-fibrosis-score","title":"NAFLD फाइब्रोसिस स्कोर (NFS)","titleLocale":"hi","summary":"यकृत स्टीटोसिस में उन्नत फाइब्रोसिस","lead":"गैर-अल्कोहलिक फैटी लिवर रोग (अब MASLD) के लिए विकसित गैर-आक्रामक स्कोर, जो उन्नत फाइब्रोसिस (F3–F4) की कम और अधिक संभावना अलग करता है।","fields":[["idade","आयु","num",{"min":18,"max":100,"unit":"वर्ष","ph":"50","unitLocale":"hi","displayLocale":"hi"}],["imc","शरीर द्रव्यमान सूचकांक (BMI)","num",{"min":12,"max":80,"step":0.1,"unit":"kg/m²","ph":"30","unitLocale":"hi","displayLocale":"hi"}],["dm","असामान्य फ़ास्टिंग ग्लूकोज़ या डायबिटीज़","radio",{"opts":{"0":"नहीं","1":"हाँ"},"unitLocale":"hi","displayLocale":"hi","optionLocales":{"0":"hi","1":"hi"}}],["ast","AST","num",{"min":1,"max":5000,"unit":"U/L","ph":"40","unitLocale":"hi","displayLocale":"hi"}],["alt","ALT","num",{"min":1,"max":5000,"unit":"U/L","ph":"50","unitLocale":"hi","displayLocale":"hi"}],["plq","प्लेटलेट्स","num",{"min":5,"max":1500,"unit":"× 10³/mm³","ph":"200","unitLocale":"hi","displayLocale":"hi"}],["alb","एल्ब्यूमिन","num",{"min":1,"max":6,"step":0.1,"unit":"g/dL","ph":"4.0","unitLocale":"hi","displayLocale":"hi"}]],"formula":"<p>NFS = −1.675 + 0.037 × आयु + 0.094 × BMI + 1.13 × (असामान्य ग्लाइसीमिया/मधुमेह: 1) + 0.99 × AST/ALT − 0.013 × प्लेटलेट्स (10⁹/L) − 0.66 × एल्ब्यूमिन (g/dL).</p>","sources":[["Angulo P et al. The NAFLD fibrosis score: a noninvasive system that identifies liver fibrosis in patients with NAFLD. Hepatology, 2007.","https://doi.org/10.1002/hep.21496"],["McPherson S et al. Age as a confounding factor for the accurate non-invasive diagnosis of advanced NAFLD fibrosis. Am J Gastroenterol, 2017.","https://doi.org/10.1038/ajg.2016.453"],["Rinella ME et al. AASLD Practice Guidance on the clinical assessment and management of nonalcoholic fatty liver disease. Hepatology, 2023.","https://doi.org/10.1097/HEP.0000000000000323"]],"methodVersion":"Angulo और सहकर्मियों (2007) का NFS छह चर उपयोग करता है; मूल सूत्र और कटऑफ McPherson और सहकर्मियों (2017) की तालिका 1 से मिलाए गए हैं। यह कार्यान्वयन ≥65 वर्ष की आयु पर निचला कटऑफ 0.12 उपयोग करता है; ऊपरी कटऑफ 0.676 रहता है।","methodVersionLocale":"hi","implementationVersion":"nafld-fibrosis-score@native-2026-10-05+325fbd4c60c4","limits":"मूल मॉडल बायोप्सी से पुष्टि किए गए NAFLD से बनाया गया था, वर्तमान में MASLD कहलाने वाली सभी आबादियों से नहीं। McPherson (2017) ने यूरोपीय विशेषज्ञ केंद्रों का मूल्यांकन किया, अन्य यकृत रोगों तथा अत्यधिक शराब सेवन को बाहर रखा और ≤35 वर्ष के लोगों में खराब प्रदर्शन पाया। चित्र 4 और उसके विवरण में 35 तथा 65 वर्ष की सीमाओं पर अंतर है; इन ठीक उम्रों का यहाँ नैदानिक निर्णय नहीं किया गया है। ≥65 वर्ष पर निचला कटऑफ 0.12 उपयोग करना इस कार्यान्वयन की घोषित नीति है। प्लेटलेट की इकाई ×10³/mm³ संख्यात्मक रूप से ×10⁹/L के बराबर है; एल्ब्यूमिन g/dL में होना चाहिए। स्कोर तीन दशमलव स्थानों तक दिखता है; वर्गीकरण स्कोर को राउंड किए बिना सख्त कटऑफ उपयोग करता है। बीच के मान निष्कर्षहीन हैं; अकेला NFS, F3–F4 की पुष्टि नहीं करता। स्वतंत्र पेशेवरों द्वारा नैदानिक और भाषा समीक्षा नहीं की गई है।","limitsLocale":"hi","resultLabels":{"NAFLD Fibrosis Score":"NAFLD फाइब्रोसिस स्कोर","NAFLD Fibrosis Score (NFS)":"NAFLD फाइब्रोसिस स्कोर (NFS)"},"resultUnits":{},"resultValues":{},"resultNarratives":[{"id":"8c07c847deb0b87be508","toolId":"nafld-fibrosis-score","area":"note","source":"A partir de 65 anos, o corte inferior usado é 0,12 (McPherson 2017).","target":"65 वर्ष की आयु से, उपयोग किया जाने वाला निचला कटऑफ 0,12 है (McPherson 2017)।"},{"id":"db3b0ead54d32c734597","toolId":"nafld-fibrosis-score","area":"verdict","source":"Resultado indeterminado: complementar com elastografia","target":"अनिर्धारित परिणाम: इलास्टोग्राफी से पूरक करें"},{"id":"def6a6cc82a5b0ee6b0d","toolId":"nafld-fibrosis-score","area":"verdict","source":"Fibrose avançada (F3–F4) improvável","target":"उन्नत फाइब्रोसिस (F3–F4) की संभावना कम है"},{"id":"13bd258cf7cc3927cd57","toolId":"nafld-fibrosis-score","area":"verdict","source":"Fibrose avançada (F3–F4) provável","target":"उन्नत फाइब्रोसिस (F3–F4) की संभावना है"}]},"shared":{"select":"चुनें","yes":"हाँ","no":"नहीं","optional":"वैकल्पिक","numeric":"संख्यात्मक मान","range":"सीमा","calculate":"गणना करें","calculating":"गणना जारी है…","clear":"साफ़ करें","heading":"पारदर्शिता के साथ गणना","intro":"जनसमूह, इकाइयाँ और संस्करण जाँचें। परिणाम सूत्र या वर्गीकरण दिखाता है; यह स्वतः उपचार संबंधी निर्णय नहीं देता।","restricted":"रिकॉर्ड देखने के लिए उपलब्ध है","restrictedNote":"इस संस्करण में गणना रुकी हुई है। सूची, लंबित समीक्षा और स्रोत सार्वजनिक हैं।","resultNote":"सूत्र या वर्गीकरण का परिणाम। व्याख्या, कार्यवाही और उपयुक्तता पेशेवर मूल्यांकन और चुने गए स्रोत पर निर्भर है।","invalid":"इन मानों से गणना नहीं हो सकी। उपयोग की शर्तें जाँचें।","unavailable":"गणना सेवा उपलब्ध नहीं है। फिर प्रयास करें।","connection":"गणना सेवा से संपर्क नहीं हो सका। कनेक्शन जाँचकर फिर प्रयास करें।","check":"दर्ज मान जाँचें।","fleischner":"गणना से पहले: आकस्मिक रूप से पाए गए फेफड़ों के नोड्यूल के लिए संदर्भ। सिफ़ारिशें 35 वर्ष से कम आयु, फेफड़ों के कैंसर की स्क्रीनिंग, प्रतिरक्षा दमन या ज्ञात प्राथमिक कैंसर पर लागू नहीं होतीं।","incompleteAssessment":"पूर्ण मूल्यांकन के बिना कुल स्कोर नहीं निकाला जा सकता।"},"ui":{"brand":"ELUCENIA · एकीकरण कोड","clinical":"स्वतंत्र नैदानिक समीक्षा नहीं की गई है।","conditions":"शर्तें, स्रोत और अनुमतियाँ","record":"रिकॉर्ड और संदर्भ","code":"JavaScript कोड","cases":"संदर्भ मामले","language":"भाषा","formula":"दस्तावेज़ित सूत्र","edition":"विधि का संस्करण","limits":"सीमाएँ और जनसमूह","references":"संदर्भ"}}}};
